using AdventOfCode;

namespace AoC2015;

public class Day1 : DayBase
{
    public override string Part1()
    {
        var floor = 0;
        foreach (var c in Input)
        {
            if (c == '(')
            {
                floor++;
            }
            else if (c == ')')
            {
                floor--;
            }
        }

        return floor.ToString();
    }

    public override string Part2()
    {
        var floor = 0;
        var input = Input;
        for (var i = 0; i < input.Length; i++)
        {
            if (input[i] == '(')
            {
                floor++;
            }
            else if (input[i] == ')')
            {
                floor--;
            }

            if (floor == -1)
            {
                return (i + 1).ToString();
            }
        }

        return "No basement entry";
    }

